<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/private/SetupWizard.php';
if(getenv('OSMON_TEST_DATABASE')!=='osmon_test'){fwrite(STDERR,"Dedicated test environment required\n");exit(1);}
$c=['host'=>getenv('OSMON_TEST_HOST')?:'127.0.0.1','port'=>(int)(getenv('OSMON_TEST_PORT')?:3306),'database'=>'osmon_test','username'=>getenv('OSMON_TEST_USER')?:'root','password'=>getenv('OSMON_TEST_PASSWORD')?:'test-only'];
$control=connectFamily($c);$control->exec('CREATE DATABASE IF NOT EXISTS osmon_setup_test CHARACTER SET utf8mb4');$c['database']='osmon_setup_test';
$dir=sys_get_temp_dir().'/osmon-setup-'.bin2hex(random_bytes(8));mkdir($dir,0700);$now=1000000.0;$wizard=new SetupWizard($dir,static function()use(&$now){return $now;});$session='';$csrf='';
function yes(bool $v,string $msg='Assertion failed'):void{if(!$v)throw new RuntimeException($msg);}
function fails(int $code,Closure $fn):void{try{$fn();}catch(FamilyAPIError$e){yes($e->status===$code,'Unexpected status '.$e->status);return;}throw new RuntimeException('Missing error '.$code);}
function resetWizard():string{global$dir,$wizard,$now,$session,$csrf,$c;foreach(glob($dir.'/{*,.*}',GLOB_BRACE)as$p)if(is_file($p))unlink($p);$db=connectFamily($c);$db->exec('SET FOREIGN_KEY_CHECKS=0');foreach($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN)as$t)$db->exec('DROP TABLE `'.str_replace('`','``',$t).'`');$db->exec('SET FOREIGN_KEY_CHECKS=1');$now=1000000.0;$session='';$csrf='';return $wizard->start('https://parents.example.test');}
function go(string $route,array $body=[],string $method='POST'):array{global$wizard,$session,$csrf;return $wizard->dispatch($method,$route,$session,$body,$csrf,'192.0.2.1');}
function unlockWizard():void{global$session,$csrf;$code=resetWizard();$r=go('unlock',['code'=>$code]);$session=$r['session'];$csrf=$r['csrf'];}
function databaseBody():array{global$c;return array_intersect_key($c,array_flip(['host','port','database','username','password']));}
function adminStep():array{unlockWizard();go('database',databaseBody());return go('admin',['username'=>'operator','password'=>'Test-only-password-123','repeat'=>'Test-only-password-123']);}
$tests=[];
$tests['code required and unauthenticated status minimal']=function(){global$wizard;resetWizard();$r=go('status',[],'GET');yes(!$r['authenticated']);yes(!isset($r['csrf'])&&!isset($r['checks']));fails(401,fn()=>go('database',databaseBody()));fails(401,fn()=>go('unlock',['code'=>'invalid']));};
$tests['single use setup code']=function(){global$session,$csrf;$code=resetWizard();$r=go('unlock',['code'=>$code]);$session=$r['session'];$csrf=$r['csrf'];yes($r['stage']==='database');fails(401,fn()=>go('unlock',['code'=>$code]));};
$tests['expiry and csrf']=function(){global$now,$wizard,$session;unlockWizard();fails(403,fn()=>$wizard->dispatch('POST','database',$session,databaseBody(),'wrong','192.0.2.1'));$now+=1801;fails(410,fn()=>go('status',[],'GET'));};
$tests['bootstrap rate limit']=function(){resetWizard();for($i=0;$i<6;$i++)fails(401,fn()=>go('unlock',['code'=>'wrong']));fails(429,fn()=>go('unlock',['code'=>'wrong']));};
$tests['existing database rejected without changing data']=function(){global$c;unlockWizard();$db=connectFamily($c);$db->exec('CREATE TABLE unrelated(id INT)');$db->exec('INSERT INTO unrelated VALUES (42)');fails(409,fn()=>go('database',databaseBody()));yes((int)$db->query('SELECT id FROM unrelated')->fetchColumn()===42);};
$tests['invalid database credentials sanitized']=function(){unlockWizard();$b=databaseBody();$b['password']='invalid-password';fails(400,fn()=>go('database',$b));$b=databaseBody();$b['host']='localhost;dbname=other';fails(400,fn()=>go('database',$b));};
$tests['database prepare idempotent within same setup']=function(){unlockWizard();$a=go('database',databaseBody());yes($a['stage']==='admin');$b=go('database',databaseBody());yes($b['stage']==='admin');yes(!isset($b['config'])&&!isset($b['password']));};
$tests['password confirmation and sequencing']=function(){unlockWizard();fails(409,fn()=>go('finish',['code'=>'000000']));fails(409,fn()=>go('admin',['username'=>'operator','password'=>'Test-only-password-123','repeat'=>'Test-only-password-123']));go('database',databaseBody());fails(400,fn()=>go('admin',['username'=>'operator','password'=>'Test-only-password-123','repeat'=>'wrong']));};
$tests['admin password only stored hashed and seed protected by session']=function(){global$dir,$wizard;$a=adminStep();yes($a['stage']==='authenticator'&&strlen($a['secret'])===32);$state=(string)file_get_contents($dir.'/.setup-state.json');yes(!str_contains($state,'Test-only-password-123'));$r=$wizard->dispatch('GET','status','',[],'','192.0.2.1');yes(!isset($r['secret']));yes((fileperms($dir.'/.setup-state.json')&0077)===0);};
$tests['wrong OTP bounded and no config written']=function(){global$dir;$a=adminStep();for($i=0;$i<10;$i++)fails(400,fn()=>go('finish',['code'=>'invalid']));fails(429,fn()=>go('finish',['code'=>'invalid']));yes(!file_exists($dir.'/config.php'));};
$tests['finish creates locked config and encrypted admin']=function(){global$now,$dir,$wizard,$c;$a=adminStep();$secret=base32Decode($a['secret']);$code=totpCode($secret,(int)floor($now/30));$r=go('finish',['code'=>$code]);yes($r['complete']);yes(file_exists($dir.'/config.php')&&file_exists($dir.'/.setup-complete'));yes(!file_exists($dir.'/.setup-state.json'));yes((fileperms($dir.'/config.php')&0077)===0);$cfg=require$dir.'/config.php';yes($cfg['database']==='osmon_setup_test');$db=connectFamily($c);$admin=$db->query('SELECT * FROM osmon_admins')->fetch();yes(password_verify('Test-only-password-123',$admin['password_hash']));yes(decryptAdminSecret($admin['totp_secret'],hex2bin($cfg['admin_key']),$admin['id'])===$secret);fails(410,fn()=>go('finish',['code'=>$code]));fails(409,fn()=>$wizard->start('https://parents.example.test'));$auth=new AdminStore($db,hex2bin($cfg['admin_key']),static function()use(&$now){return$now;});fails(401,fn()=>$auth->login(['username'=>'operator','password'=>'Test-only-password-123','code'=>$code]));$now+=30;yes(isset($auth->login(['username'=>'operator','password'=>'Test-only-password-123','code'=>totpCode($secret,(int)floor($now/30))])['token']));};
$tests['existing config cannot be overwritten']=function(){global$dir,$wizard;resetWizard();file_put_contents($dir.'/config.php','<?php return [];');fails(409,fn()=>$wizard->start('https://parents.example.test'));fails(410,fn()=>go('unlock',['code'=>'anything']));yes(file_get_contents($dir.'/config.php')==='<?php return [];');};
$failed=0;foreach($tests as$name=>$test){try{$test();echo"PASS $name\n";}catch(Throwable$e){$failed++;fwrite(STDERR,"FAIL $name: ".$e->getMessage()."\n");}}
foreach(glob($dir.'/{*,.*}',GLOB_BRACE)as$p)if(is_file($p))unlink($p);rmdir($dir);echo count($tests)." setup tests, $failed failures\n";exit($failed?1:0);
